\set ON_ERROR_STOP on
begin;
do $$ declare a uuid:='00000000-0000-4000-8000-000000000001';b uuid:='00000000-0000-4000-8000-000000000002';t uuid:='10000000-0000-4000-8000-000000000001';bank uuid;job uuid;other uuid;rows jsonb;stage jsonb;result jsonb;data jsonb;view jsonb;stamp timestamptz;
begin
 bank:=(public.assessment_command(a,t,'import-bank-001','bank.create','{"title":"Imported center bank"}')->>'id')::uuid;
 select jsonb_agg(jsonb_build_object('line',n,'item',jsonb_build_object('schema_version','assessment.item.v1','type','short_answer','locale','en','prompt','Imported question '||n,'max_score',1,'tags','[]'::jsonb),'key',jsonb_build_object('correct','Answer '||n),'warnings','[]'::jsonb,'fingerprint',repeat('a',64))) into rows from generate_series(1,60)n;
 data:=jsonb_build_object('bank_id',bank,'source_name','reviewed.csv','format','csv','source_hash',repeat('b',64),'rows',rows);
 stage:=public.assessment_bank_import_command(a,t,'import-stage-001','stage',data);job:=(stage->>'id')::uuid;
 if public.assessment_bank_import_command(a,t,'import-stage-001','stage',data)<>stage then raise exception 'Stage receipt changed';end if;
 if (select count(*) from assessment_items where bank_id=bank)<>0 then raise exception 'Staging created live items';end if;
 if public.assessment_bank_import_command(a,t,'import-stage-002','stage',data)->>'id'<>job::text then raise exception 'Same source duplicated import';end if;
 begin perform public.assessment_bank_import_command(a,t,'import-bad-hash','confirm',jsonb_build_object('id',job,'expected_revision',1,'review_hash',repeat('c',64),'reason','Reviewed'));raise exception 'Changed review accepted';exception when unique_violation then null;end;
 begin perform public.assessment_bank_import_read('00000000-0000-4000-8000-000000000004',t,'job',job,0,50);raise exception 'Foreign actor read private answer keys';exception when insufficient_privilege then null;end;
 begin perform public.assessment_bank_import_command(a,t,'import-unconfirmed','step',jsonb_build_object('id',job,'expected_revision',1));raise exception 'Unconfirmed import advanced';exception when insufficient_privilege then null;end;
 perform public.assessment_bank_import_command(a,t,'import-confirm-001','confirm',jsonb_build_object('id',job,'expected_revision',1,'review_hash',stage->>'review_hash','reason','Reviewed file, bank and warnings'));
 data:=jsonb_build_object('id',job,'expected_revision',2);result:=public.assessment_bank_import_command(a,t,'import-step-001','step',data);
 if result->>'processed'<>'50' or result->>'state'<>'importing' then raise exception 'Import batch was not bounded';end if;
 if public.assessment_bank_import_command(a,t,'import-step-001','step',data)<>result then raise exception 'Lost step reply duplicated batch';end if;
 begin perform public.assessment_bank_import_command(a,t,'import-stale-001','step',data);raise exception 'Stale import revision advanced';exception when unique_violation then null;end;
 update tenant_memberships set status='inactive' where tenant_id=t and user_id=a;
 begin perform public.assessment_bank_import_command(a,t,'import-step-001','step',data);raise exception 'Revoked author replayed receipt';exception when insufficient_privilege then null;end;
 begin perform public.assessment_bank_import_command(b,t,'import-silent-adopt','step',jsonb_build_object('id',job,'expected_revision',3));raise exception 'Another author silently adopted import';exception when insufficient_privilege then null;end;
 perform public.assessment_bank_import_command(b,t,'import-adopt-001','confirm',jsonb_build_object('id',job,'expected_revision',3,'review_hash',stage->>'review_hash','reason','Reviewed and adopted remaining targets'));
 perform public.assessment_bank_import_command(b,t,'import-step-002','step',jsonb_build_object('id',job,'expected_revision',4));
 update tenant_memberships set status='active' where tenant_id=t and user_id=a;
 if (select count(*) from assessment_items where bank_id=bank)<>60 or exists(select 1 from assessment_item_versions v join assessment_items i on i.id=v.item_id where i.bank_id=bank and (v.status<>'draft' or v.approved_by is not null)) then raise exception 'Import duplicates/approval bypass';end if;
 view:=public.assessment_bank_import_read(b,t,'job',job,50,50);if jsonb_array_length(view->'rows')<>10 or view->'rows'->0->>'line'<>'51' then raise exception 'Private review pagination failed';end if;
 view:=public.assessment_bank_export(b,t,bank,null,null,50);stamp:=(view->>'snapshot_at')::timestamptz;if jsonb_array_length(view->'rows')<>50 or view->'rows'->0->'key' is null then raise exception 'Protected bank export failed';end if;
 if jsonb_array_length(public.assessment_bank_export(b,t,bank,(view->'rows'->49->>'id')::uuid,stamp,50)->'rows')<>10 then raise exception 'Export pagination failed';end if;
 begin perform public.assessment_bank_export('00000000-0000-4000-8000-000000000004',t,bank,null,null,50);raise exception 'Foreign export accepted';exception when insufficient_privilege then null;end;
 begin update assessment_bank_import_rows set item='{}' where import_id=job;raise exception 'Manifest changed';exception when check_violation then null;end;
 data:=jsonb_build_object('bank_id',bank,'source_name','cancel.csv','format','csv','source_hash',repeat('d',64),'rows',rows);stage:=public.assessment_bank_import_command(a,t,'import-stage-cancel','stage',data);other:=(stage->>'id')::uuid;
 perform public.assessment_bank_import_command(a,t,'import-confirm-cancel','confirm',jsonb_build_object('id',other,'expected_revision',1,'review_hash',stage->>'review_hash','reason','Reviewed cancellation test'));
 perform public.assessment_bank_import_command(a,t,'import-partial-cancel','step',jsonb_build_object('id',other,'expected_revision',2));
 perform public.assessment_bank_import_command(a,t,'import-cancel-001','cancel',jsonb_build_object('id',other,'expected_revision',3,'reason','Stop remaining drafts'));
 if (select count(*) from assessment_bank_import_rows where import_id=other and state='created')<>50 or (select count(*) from assessment_bank_import_rows where import_id=other and state='cancelled')<>10 then raise exception 'Cancel erased or created drafts';end if;
 if has_function_privilege('authenticated','public.assessment_bank_import_command(uuid,uuid,text,text,jsonb)','execute') or has_table_privilege('authenticated','assessment_bank_import_rows','select') then raise exception 'Raw import privilege leaked';end if;
end;$$;
rollback;
